# search_index_server.py, the server being called by research_server.py
# Give the downstream call a firm timeout so a slow or stuck search
# index cannot stall the research server, and by extension, whoever
# called the research server in the first place.

import asyncio

async def call_downstream(session, query):
    try:
        return await asyncio.wait_for(
            session.call_tool("search", {"query": query}),
            timeout=3.0,
        )
    except asyncio.TimeoutError:
        raise RuntimeError("downstream search server timed out")

