# report_server.py
@server.call_tool()
async def handle_call_tool(name, arguments):
    if name != "summarize_activity":
        raise ValueError(f"unknown tool: {name}")

    async with stdio_client(BILLING_SERVER) as (read, write):
        async with ClientSession(read, write) as session:
            await session.initialize()
            try:
                charges = await asyncio.wait_for(
                    session.call_tool(
                        "get_charges", {"customer_id": arguments["customer_id"]}
                    ),
                    timeout=3.0,
                )
            except asyncio.TimeoutError:
                raise RuntimeError("report_server: billing_server timed out")
            except Exception as exc:
                raise RuntimeError(f"report_server: billing_server call failed: {exc}") from exc

    return summarize(charges.content)
